async def seed_database(force: bool = False):
    """Idempotently seed demo accounts and initial departmental data."""
    user_count = await db.users.count_documents()
    if user_count > 0 and not force:
        print("[Seed] Database already seeded. Skipping initial seeding.")
        return

    print("[Seed] Seeding initial users and academic data...")

    # Seed demo student
    await db.users.insert_one({
        "id": "7f769313-537d-552f-9e77-5b315efb2559",
        "name": "Amanpreet Singh",
        "email": "aman.cse084@mrsptu.ac.in",
        "password_hash": hash_password("student123"),
        "role": "student",
        "roll_no": "2021CSE084",
        "branch": "B.Tech CSE",
        "semester": "8th Semester (Final Year)",
        "batch": "2021-2025",
        "cgpa": "8.74",
        "attendance": "88.5%",
        "designation": "",
    })

    # Seed demo administrator
    await db.users.insert_one({
        "id": "a2d35653-e0be-54d3-867d-4787e6d7cd1f",
        "name": "Dr. Hardeep Singh",
        "email": "hod.cse@mrsptu.ac.in",
        "password_hash": hash_password("admin123"),
        "role": "admin",
        "roll_no": "",
        "branch": "Computer Science & Engineering",
        "semester": "",
        "batch": "",
        "cgpa": "",
        "attendance": "",
        "designation": "Head of Department & Viva Examination Coordinator",
    })

    # Seed subjects
    for s in INITIAL_SUBJECTS:
        await db.subjects.insert_one(s)

    # Seed timetable
    for t in INITIAL_TIMETABLE:
        await db.timetable.insert_one(t)

    # Seed assignments
    for a in INITIAL_ASSIGNMENTS:
        await db.assignments.insert_one(a)

    # Seed resources
    for r in INITIAL_RESOURCES:
        await db.resources.insert_one(r)

    # Seed notices
    for n in INITIAL_NOTICES:
        await db.notices.insert_one(n)

    # Seed events
    for e in INITIAL_EVENTS:
        await db.events.insert_one(e)

    # Seed support tickets
    for sup in INITIAL_SUPPORT:
        await db.support_tickets.insert_one(sup)

    print("[Seed] Initial database seeding completed successfully.")

if __name__ == "__main__":
    asyncio.run(seed_database(force=True))
